#!/usr/bin/env python3
# Python 3.6+; exact-version, backed-up installation.
import base64,hashlib,json,sys
PAYLOAD = json.loads('{"ryu/network_shortest_path.py": {"before": "252d8f7f07aa7c78de1c169119dce6185c7c9d797101434d416b9cf77f08649a", "after": "1918b4c261fe04357068ab0bf728f586f65499e079faed98614d73ba904768ef", "data": ""}, "ryu/network_structure.py": {"before": "bbc7c19bcbebf441b61204e2e88884268ef97ef5f9afce3716fe1d5763252ef3", "after": "77cdc57205fec5d4dc624ef3f8f03f11fc345c1b4afbc8c161e226268f5e6944", "data": ""}, "ryu/perflow_controller.py": {"before": "c8055c31df4e1425f3f163fc6391cce91f893acbbce0de19fa8a25f4bc9fbcff", "after": "1de182109e8f41d2c984204519a0614c9c16b29b521299d7562d8915549e12a8", "data": ""}}')

def main():
    import argparse,datetime,os,shutil,tempfile
    from pathlib import Path
    ap=argparse.ArgumentParser(description='Ryu stability patch; exact source matching and automatic backup.')
    ap.add_argument('--check',action='store_true',help='Check compatibility without changing files')
    args=ap.parse_args()
    root=Path(__file__).resolve().parent
    if not (root/'ryu').is_dir():
        sys.exit('Place this file in the Mininet project root, beside anycast_tcp_client.py.')
    changes=[]
    for name,item in PAYLOAD.items():
        p=root/name
        if not p.is_file():sys.exit('MISSING: '+str(p)+'; no files changed.')
        raw=p.read_bytes();digest=hashlib.sha256(raw).hexdigest()
        new=base64.b64decode(item['data'])
        compile(new.decode('utf-8'),name,'exec')
        if digest==item['after']:
            print('ALREADY PATCHED: '+name);continue
        if digest!=item['before']:
            sys.exit('VERSION MISMATCH: '+name+'; no files changed. Send your current file for merging. Do not force overwrite.')
        changes.append((p,raw,new));print('COMPATIBLE: '+name)
    if args.check or not changes:
        print('Check complete. No files changed.');return
    for entry in Path('/proc').iterdir():
        if not entry.name.isdigit():continue
        try:parts=(entry/'cmdline').read_bytes().split(b'\0')
        except OSError:continue
        if any(Path(os.fsdecode(x)).name in ('ryu-manager','ryu-manager.py') for x in parts[:3]) or any(x in (b'ryu.cmd.manager',b'ryu.cmd.manager.py') for x in parts):
            sys.exit('Ryu is still running (PID '+entry.name+'). Stop the client and Ryu first; keep Mininet. No files changed.')
    backup=root/'runtime'/('stability_backup_'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    backup.mkdir(parents=True)
    for p,old,new in changes:
        dest=backup/p.relative_to(root);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(str(p),str(dest))
    def atomic_write(p,data):
        fd,tmp=tempfile.mkstemp(prefix=p.name+'.patch.',dir=str(p.parent))
        try:
            with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
            os.chmod(tmp,p.stat().st_mode & 0o777)
            os.replace(tmp,str(p))
        finally:
            if os.path.exists(tmp):os.unlink(tmp)
    try:
        for p,old,new in changes:atomic_write(p,new)
    except Exception:
        for p,old,new in changes:atomic_write(p,old)
        raise
    print('PATCH APPLIED. Backup: '+str(backup))
    print('Restart Ryu with your ORIGINAL command. Keep Mininet running during lease cleanup.')
    print('Before training: verify pending_leases=0 and the complete expected topology (24 links).')
    print('New log markers: TOPOLOGY_CHANGE, OF_CONNECT, OF_DISCONNECT, waiting_barriers, waiting_stats.')
    print('This patch adds bounded behavior and diagnosis; it does not repair physical disconnections or add training resume.')

if __name__=='__main__':
    main()
